templates.body:
if e == null then "<missing expression>"
else if e.instanceOf.name == "Ref" then e.name
else if e.instanceOf.name == "Const" then constLit(e.width, e.value, L)
else if e.instanceOf.name == "Neg" then sp("neg", L) + "(" + expr(e.op, L) + ")"
else if e.instanceOf.name == "Conj" then nary(e.ops, sp("conj", L), sp("tru", L), L)
else if e.instanceOf.name == "Disj" then nary(e.ops, sp("disj", L), sp("fls", L), L)
else if e.instanceOf.name == "Eq" then "(" + expr(e.left, L) + sp("eq", L) + expr(e.right, L) + ")"
else if e.instanceOf.name == "Implies" then impl(e, L)
else if e.instanceOf.name == "Ite" then "(" + expr(e.cond, L) + " ? " + expr(e.ifTrue, L) + " : " + expr(e.ifFalse, L) + ")"
else if e.instanceOf.name == "Prev" then temporal("Y", e, L)
else if e.instanceOf.name == "Next" then temporal("X", e, L)
else if e.instanceOf.name == "Globally" then temporal("G", e, L)
else "<unknown expression " + e.instanceOf.name + ">"

if v == null then "<missing value>"
else if L == "smv" then (if w == 1 then (if v == 0 then "FALSE" else "TRUE") else "0ud" + w + "_" + v)
else w + "'d" + v

// ${m.name}: generated by Jjodel from a SyncRTL model (Verilog-2001 printer).
// One clock, synchronous active-high reset, non-blocking register updates.
// INVAR properties become simulation-only checks under `ifdef ASSERTIONS ($display and $finish, plain Verilog-2001).
// LTL properties are checked by nuXmv on the same model and are not printed here.
module ${m.name} (
  ${vPorts(m)}
);
  ${m.regs.map(r => "reg  " + vRange(r.width) + r.name + ";").join("\n  ")}
  ${m.wires.map(w => "wire " + vRange(w.width) + w.name + ";").join("\n  ")}

  ${m.wires.map(w => "assign " + w.name + " = " + expr(w.expr, L) + ";").join("\n  ")}
  ${m.outputs.map(p => "assign " + p.name + " = " + expr(p.driver, L) + ";").join("\n  ")}

  always @(posedge clk) begin
    if (rst) begin
      ${m.regs.map(r => r.name + " <= " + constLit(r.width, r.reset, L) + ";").join("\n      ")}
    end else begin
      ${m.regs.map(r => r.name + " <= " + expr(r.next, L) + ";").join("\n      ")}
    end
  end

`ifdef ASSERTIONS
  always @(posedge clk) if (!rst) begin
    ${m.properties.filter(p => p.kind == "INVAR").map(p => "if (!" + expr(p.expr, L) + ") begin $display(\"" + m.name + ": property " + p.name + " violated at %0t\", $time); $finish; end").join("\n    ")}
  end
`endif
endmodule
